## 3. Result-Generation Logic (form data → recommendation)

The result logic is defined inline in the Compass page (no separate lib file). Below are the `CSAInputs` interface, `defaultInputs`, and the `evaluate()` function extracted verbatim.

Source: `client/src/pages/CentralSleepApneaCompass.tsx`

```typescript
interface CSAInputs {
  ahi: string;
  cai: string;
  cai_percent: string;
  psg_performed: boolean;
  etiology: "idiopathic" | "cheyneStokes" | "opioid" | "highAltitude" | "treatmentEmergent" | "cardiac" | "unknown";
  comorbid_hf: boolean;
  comorbid_af: boolean;
  comorbid_stroke: boolean;
  comorbid_osa: boolean;
  comorbid_obesity: boolean;
  bmi: string;
  opioid_use: boolean;
  opioid_mme: string;
  current_cpap: boolean;
  current_bpap: boolean;
  current_asv: boolean;
  ef_percent: string;
  lvef_reduced: boolean;
  nyha_class: "I" | "II" | "III" | "IV" | "unknown";
}

const defaultInputs: CSAInputs = {
  ahi: "",
  cai: "",
  cai_percent: "",
  psg_performed: false,
  etiology: "unknown",
  comorbid_hf: false,
  comorbid_af: false,
  comorbid_stroke: false,
  comorbid_osa: false,
  comorbid_obesity: false,
  bmi: "",
  opioid_use: false,
  opioid_mme: "",
  current_cpap: false,
  current_bpap: false,
  current_asv: false,
  ef_percent: "",
  lvef_reduced: false,
  nyha_class: "unknown",
};

function evaluate(inputs: CSAInputs) {
  const ahi = parseFloat(inputs.ahi);
  const cai = parseFloat(inputs.cai);
  const caiPercent = parseFloat(inputs.cai_percent);
  const bmi = parseFloat(inputs.bmi);
  const ef = parseFloat(inputs.ef_percent);

  const csaDiagnosis = cai >= 5 && caiPercent > 50;
  const severity: "mild" | "moderate" | "severe" =
    ahi >= 30 ? "severe" : ahi >= 15 ? "moderate" : "mild";

  const recommendations: string[] = [];
  const contraindications: string[] = [];
  const notes: string[] = [];

  // AASM 2025 CSA CPG
  if (inputs.etiology === "cheyneStokes" || inputs.comorbid_hf) {
    if (inputs.lvef_reduced || ef < 45) {
      contraindications.push("ASV is CONTRAINDICATED in HFrEF (EF <45%) with predominantly CSA — AASM 2025 / SERVE-HF trial: increased cardiovascular mortality");
      recommendations.push("Optimize heart failure therapy (ACE-I/ARB, beta-blocker, diuretics, SGLT2 inhibitor)");
      recommendations.push("CPAP: Conditionally recommended for Cheyne-Stokes respiration in HFrEF (AASM 2025)");
      recommendations.push("Supplemental oxygen: Conditionally recommended for CSA-CSR in HFrEF");
    } else {
      recommendations.push("ASV: Conditionally recommended for CSA-CSR in HFpEF (EF ≥45%) — AASM 2025");
      recommendations.push("CPAP: Conditionally recommended as first-line for CSA-CSR");
    }
  } else if (inputs.etiology === "opioid" || inputs.opioid_use) {
    recommendations.push("Reduce opioid dose if clinically feasible (most effective intervention)");
    recommendations.push("BPAP with backup rate: Conditionally recommended for opioid-induced CSA — AASM 2025");
    recommendations.push("ASV: Conditionally recommended for opioid-induced CSA — AASM 2025");
    notes.push(`Opioid dose: ${inputs.opioid_mme || "?"} MME/day — CSA risk increases significantly above 200 MME/day`);
  } else if (inputs.etiology === "treatmentEmergent") {
    recommendations.push("Continue CPAP — treatment-emergent CSA often resolves within 1–3 months");
    recommendations.push("If persistent ≥3 months: switch to ASV (Conditionally recommended — AASM 2025)");
    recommendations.push("If ASV not tolerated: BPAP with backup rate");
  } else if (inputs.etiology === "idiopathic") {
    recommendations.push("CPAP: Suggested as initial therapy for idiopathic CSA — AASM 2025");
    recommendations.push("ASV: Conditionally recommended if CPAP inadequate");
    recommendations.push("Acetazolamide 250–500 mg BID: Conditionally recommended for idiopathic CSA");
  } else {
    recommendations.push("CPAP: First-line trial for most CSA etiologies — AASM 2025");
    recommendations.push("ASV: Conditionally recommended if CPAP inadequate (except HFrEF)");
  }

  // GLP-1 / Zepbound note for comorbid obesity
  if (inputs.comorbid_obesity || bmi >= 30) {
    notes.push("GLP-1/GIP Agonist (Tirzepatide/Zepbound): FDA-approved December 2024 for moderate-to-severe OSA with obesity. SURMOUNT-OSA trial: 50.7% mean AHI reduction (vs 29.3% placebo). Primarily studied for OSA, but weight loss may improve CSA in obese patients with CSA-OSA overlap. Prior auth required; BMI ≥30 with OSA diagnosis required.");
  }

  const authRequired = true;
  const appealStrength: "strong" | "moderate" | "weak" = csaDiagnosis ? "strong" : "moderate";

  const keyFindings: string[] = [];
  if (ahi) keyFindings.push(`AHI: ${ahi} events/hour — ${severity} sleep apnea`);
  if (cai) keyFindings.push(`Central Apnea Index (CAI): ${cai} events/hour${caiPercent ? ` (${caiPercent}% of total events)` : ""}`);
  if (csaDiagnosis) keyFindings.push("CSA diagnosis criteria met: CAI ≥5 with >50% central events");
  if (inputs.lvef_reduced) keyFindings.push("⚠️ Reduced EF — ASV CONTRAINDICATED (SERVE-HF / AASM 2025)");
  if (inputs.opioid_use) keyFindings.push(`Opioid use: ${inputs.opioid_mme || "dose not specified"} MME/day — opioid-induced CSA etiology`);

  return { csaDiagnosis, severity, recommendations, contraindications, notes, authRequired, appealStrength, keyFindings };
}
